ROWS = tuple(row[:4] for header in HEADERS.values() for row in block(header))


class DailyGapWordsTests(unittest.TestCase):
    def test_blocks(self):
        for group, header in HEADERS.items():
            rows = block(header)
            self.assertEqual(SIZES[group], len(rows), group)
            if rows:
                self.assertEqual({"exact_rank_no_contains"}, {row[4] for row in rows}, group)
        self.assertEqual(len(ROWS), len({(row[0], row[1]) for row in ROWS}))
        forced = block(HEADER_FORCED)
        self.assertEqual({"exact_rank"}, {row[4] for row in forced})
        self.assertEqual({row[:4] for row in FORCED}, {tuple(row[:4]) for row in forced})

    def test_words_in_both_variants(self):
        for index, variant in enumerate(("sc", "tc"), 1):
            rows = read_rows(f"dict_clean_{variant}.txt")
            for row in ROWS + tuple(FORCED):
                pinyin, text = row[0], row[index]
                self.assertIn((pinyin, text), rows, (variant, text))

    def test_readings(self):
        for variant, pairs in READINGS.items():
            unihan = {tuple(line.split("\t")[:2])
                      for line in (ROOT / f"data/generated/dict_unihan_{variant}.txt").read_text(
                          encoding="utf-8").splitlines()}
            overrides = {tuple(line.split("\t")[:2])
                         for line in (ROOT / f"manifests/pinyin_overrides.{variant}.tsv").read_text(
                             encoding="utf-8").splitlines() if line and not line.startswith("#")}
            for char, reading in pairs:
                self.assertIn((reading, char), unihan, (variant, char, reading))
                self.assertIn((char, reading), overrides, (variant, char, reading))
